            total += dist(coord_of(route[i]), coord_of(route[i + 1]))
        total += dist(coord_of(route[-1]), depot_xy)
        return total

    def two_opt(route):
        if len(route) < 4 or coords is None:
            return route[:]
        r = route[:]
        improved = True
        while improved:
            improved = False
            m = len(r)
            for i in range(m - 2):
                a = depot_xy if i == 0 else coord_of(r[i - 1])
                b = coord_of(r[i])
                for k in range(i + 1, m - 1):
                    c = coord_of(r[k])
                    d = depot_xy if k + 1 == m else coord_of(r[k + 1])
                    if dist(a, c) + dist(b, d) + 1e-12 < dist(a, b) + dist(c, d):
                        r[i:k + 1] = r[i:k + 1][::-1]
                        improved = True
        return r

    # Improve each route with local search.
    routes = [two_opt(r) for r in routes]

    # Repair duplicates/missing customers deterministically.
    seen = {}
    final_routes = []
    final_loads = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c == depot:
                continue
            if c not in seen:
                seen[c] = 1
                nr.append(c)
                load += demand_of(c)
        if nr:
            final_routes.append(nr)
            final_loads.append(load)

    missing = []
    for c in all_nodes:
        if c not in seen:
            missing.append(c)

    # Insert missing customers into feasible routes; otherwise create singleton routes.
    for c in missing:
        d = demand_of(c)
        if d is None or d < 0:
            d = 0
        best_idx = -1
        best_increase = None

        for idx in range(len(final_routes)):
            if final_loads[idx] + d <= capacity:
                r = final_routes[idx]
                base = route_cost(r)
                best_pos = len(r)
                best_delta = None
                for pos in range(len(r) + 1):
                    prev_pt = depot_xy if pos == 0 else coord_of(r[pos - 1])
                    next_pt = depot_xy if pos == len(r) else coord_of(r[pos])
                    delta = dist(prev_pt, coord_of(c)) + dist(coord_of(c), next_pt) - dist(prev_pt, next_pt)
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_pos = pos
                if best_increase is None or best_delta < best_increase or (best_delta == best_increase and idx < best_idx):
                    best_increase = best_delta
                    best_idx = idx
                    best_pos_final = best_pos

        if best_idx >= 0:
            final_routes[best_idx].insert(best_pos_final, c)
            final_loads[best_idx] += d
        else:
            final_routes.append([c])
            final_loads.append(d)

    return final_routes
